package com.medtrack.tracking.provider; import com.medtrack.shipment.entity.Shipment; import com.medtrack.tracking.dto.TrackingEventRequest; import com.medtrack.tracking.entity.MilestoneStatus; import java.time.*; import java.util.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component;
@Component @Profile({"dev","default"}) public class MockTrackingProvider implements ShipmentTrackingProvider {public List<TrackingEventRequest> eventsFor(Shipment s){Instant t=Instant.now();return List.of(new TrackingEventRequest(MilestoneStatus.DEPARTED_DEPOT,"Origin warehouse",0d,0d,"Deterministic mock departure",t),new TrackingEventRequest(MilestoneStatus.IN_TRANSIT,"Checkpoint Alpha",0.1d,0.1d,"Deterministic mock waypoint",t.plus(Duration.ofHours(1))),new TrackingEventRequest(MilestoneStatus.OUT_FOR_DELIVERY,"Destination route",0.2d,0.2d,"Deterministic mock final leg",t.plus(Duration.ofHours(2))));}}
